'use strict';
// The export object is an accessor whose getter answers a function on every read.
let reads = 0;

function current() {
	reads += 1;
	console.log('function: read', reads);
	const made = reads;
	return function answer() {
		return made;
	};
}

Object.defineProperty(module, 'exports', {enumerable: true, get: current});
